/** The effective day as the page prints it: German day.month.year, ISO elsewhere (no Intl: the same bytes on every host). */
export function termsDate(lang: Lang): string {
  const [y, m, d] = TERMS_EFFECTIVE.split("-");
  return lang === "de" ? `${d ?? ""}.${m ?? ""}.${y ?? ""}` : TERMS_EFFECTIVE;
}
